export interface OverflowItem {
  readonly id: string;
  readonly width: number;
  readonly priority: number;
  readonly group?: string | null;
}
export interface VisibilityResult { visible: string[]; hidden: string[] }

export function chooseVisible(items: readonly OverflowItem[], capacity: number): VisibilityResult {
  if (!Number.isFinite(capacity) || capacity < 0) throw new RangeError('invalid capacity');
  const seen = new Set<string>();
  const groups = new Map<string, { indices: number[]; width: number; priority: number; first: number }>();
  items.forEach((item, index) => {
    if (seen.has(item.id)) throw new RangeError('duplicate id');
    seen.add(item.id);
    if (!Number.isFinite(item.width) || item.width < 0 || !Number.isFinite(item.priority)) {
      throw new RangeError('invalid item');
    }
    const key = item.group == null ? `#${index}` : `g:${item.group}`;
    const group = groups.get(key);
    if (group) {
      group.indices.push(index);
      group.width += item.width;
      group.priority = Math.max(group.priority, item.priority);
    } else {
      groups.set(key, { indices: [index], width: item.width, priority: item.priority, first: index });
    }
  });
  const candidates = [...groups.values()].sort((a, b) => a.priority - b.priority || a.first - b.first);
  const selected = new Set<number>();
  let remaining = capacity;
  for (const candidate of candidates) {
    if (candidate.width <= remaining) {
      candidate.indices.forEach(index => selected.add(index));
      remaining -= candidate.width;
    }
  }
  const visible: string[] = [];
  const hidden: string[] = [];
  items.forEach((item, index) => (selected.has(index) ? visible : hidden).push(item.id));
  return { visible, hidden };
}

