import { chooseVisible } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function expectRange(action: () => unknown): void {
  try { action(); } catch (error) {
    assert(error instanceof RangeError, 'invalid input throws RangeError');
    return;
  }
  throw new Error('expected RangeError');
}

const items = [
  { id: 'low', width: 2, priority: 1 },
  { id: 'g1', width: 2, priority: 3, group: 'g' },
  { id: 'high', width: 3, priority: 10 },
  { id: 'g2', width: 2, priority: 8, group: 'g' },
  { id: 'later', width: 1, priority: 2 },
];
const result = chooseVisible(items, 5);
equal(result.visible.join(','), 'g1,g2,later', 'group priority is maximum and atomic selection skips nonfitting candidates');
equal(result.hidden.join(','), 'low,high', 'hidden IDs retain original order');

const tie = chooseVisible([
  { id: 'first', width: 2, priority: 5 },
  { id: 'second', width: 2, priority: 5 },
], 2);
equal(tie.visible.join(','), 'first', 'equal priority uses earliest position');
equal(tie.hidden.join(','), 'second', 'later tie is hidden');

const atomic = chooseVisible([
  { id: 'a', width: 2, priority: 9, group: 'same' },
  { id: 'b', width: 2, priority: 1, group: 'same' },
  { id: 'c', width: 3, priority: 2 },
], 3);
equal(atomic.visible.join(','), 'c', 'oversized group is skipped as a whole and consideration continues');
equal(atomic.hidden.join(','), 'a,b', 'whole group hidden');

const zero = chooseVisible([
  { id: 'zero', width: 0, priority: -10 },
  { id: 'one', width: 1, priority: 0 },
], 0);
equal(zero.visible.join(','), 'zero', 'zero-width candidate fits zero capacity');
equal(zero.hidden.join(','), 'one', 'positive-width candidate does not fit zero capacity');
equal(JSON.stringify(chooseVisible([], 0)), JSON.stringify({ visible: [], hidden: [] }), 'empty input valid');

expectRange(() => chooseVisible([], -1));
expectRange(() => chooseVisible([], Number.NaN));
expectRange(() => chooseVisible([], Infinity));
expectRange(() => chooseVisible([{ id: 'x', width: -1, priority: 1 }], 10));
expectRange(() => chooseVisible([{ id: 'x', width: Number.NaN, priority: 1 }], 10));
expectRange(() => chooseVisible([{ id: 'x', width: 1, priority: Infinity }], 10));
expectRange(() => chooseVisible([
  { id: 'x', width: 1, priority: 1 },
  { id: 'x', width: 1, priority: 2 },
], 10));

const mutable = [{ id: 'x', width: 1, priority: 1, group: null }];
const copied = chooseVisible(mutable, 1);
assert(copied.visible !== (mutable as any), 'output array does not alias input');
copied.visible[0] = 'changed';
equal(mutable[0].id, 'x', 'output mutation does not affect input');
equal(mutable[0].width, 1, 'input record is not mutated');

